// Transpiles a converted controller in memory (nothing is written to the repository) and compares the result,
// with comments removed, against the baseline compiled copy of the original JavaScript file.
// Usage: node emitcheck.js <repo> <baseline> <outDir> <ControllerName>...
const fs = require('fs')
const path = require('path')
const [repo, baseline, outDir, ...names] = process.argv.slice(2)
const ts = require(path.join(repo, 'node_modules', 'typescript'))

const raw = ts.readConfigFile(path.join(repo, 'tsconfig.server.json'), ts.sys.readFile).config.compilerOptions
const options = ts.convertCompilerOptionsFromJson(raw, repo).options
delete options.incremental
delete options.tsBuildInfoFile
options.noEmitOnError = false

const printer = ts.createPrinter({ removeComments: true, newLine: ts.NewLineKind.LineFeed })
function normalize(text, file) {
  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.ES2022, true, ts.ScriptKind.JS)
  return sf.statements.map((s) => printer.printNode(ts.EmitHint.Unspecified, s, sf)).join('\n') + '\n'
}

for (const name of names) {
  const src = fs.readFileSync(path.join(repo, 'server', 'controllers', name + '.ts'), 'utf8')
  const result = ts.transpileModule(src, { compilerOptions: options, fileName: name + '.ts', reportDiagnostics: true })
  if (result.diagnostics && result.diagnostics.length) {
    console.log(name, 'syntax diagnostics:', result.diagnostics.map((d) => ts.flattenDiagnosticMessageText(d.messageText, '\n')))
  }
  fs.writeFileSync(path.join(outDir, name + '.emit.js'), result.outputText)
  fs.writeFileSync(path.join(outDir, name + '.new.norm.js'), normalize(result.outputText, name + '.new.js'))
  const base = fs.readFileSync(path.join(baseline, 'server', 'controllers', name + '.js'), 'utf8')
  fs.writeFileSync(path.join(outDir, name + '.base.norm.js'), normalize(base, name + '.base.js'))
  console.log(name, 'written')
}

